request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-010

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "VALIDATES_CONFIGURATION_BEFORE_ACTIVATION",
    "definition": "A validation operation checks an artifact, configuration, or prepared state for validity before the dependent component is activated or otherwise relied upon, and the observation confirms that validation succeeded.",
    "parameters": [
      {
        "name": "validation_reasoning",
        "type": "reasoning",
        "description": "The reasoning node indicating that the artifact or configuration should be validated before activation or reliance."
      },
      {
        "name": "validation_action",
        "type": "action",
        "description": "The action performing a configuration test, syntax check, or equivalent validity check; activation may occur in the same action or a subsequent one."
      },
      {
        "name": "validation_observation",
        "type": "observation",
        "description": "The observation reporting the validation result."
      }
    ],
    "assertion_conditions": [
      "The validation reasoning or validation action indicates a validation step is to be performed before the component is activated or relied upon.",
      "The validation action executes a configuration test, syntax check, or equivalent validity check on the artifact, configuration, or prepared state.",
      "The validation observation reports a successful validation result, and activation or reliance follows that success."
    ],
    "exclusion_conditions": [
      "The component is activated or relied upon without any preceding validation step.",
      "The validation fails or its result is not interpretable as success.",
      "Only a post-activation inspection is performed, with no pre-activation or pre-reliance check."
    ]
  },
  {
    "name": "CONFIRMS_PERSISTED_OUTPUT_MATCHES_COMPUTED_VALUE",
    "definition": "An action inspects the persisted output artifact, and its observation shows artifact content identical to a value the agent previously computed, confirming that the stored output faithfully reflects the computed result.",
    "parameters": [
      {
        "name": "computed_result",
        "type": "observation",
        "description": "The observation reporting the value produced by the computation."
      },
      {
        "name": "inspection_action",
        "type": "action",
        "description": "The action that reads, lists, or otherwise inspects the persisted output artifact."
      },
      {
        "name": "artifact_observation",
        "type": "observation",
        "description": "The observation showing the content of the persisted output artifact."
      }
    ],
    "assertion_conditions": [
      "The computed result observation reports a specific value produced by the agent's computation.",
      "The inspection action targets the file or artifact to which that value was written.",
      "The artifact observation shows content whose value is identical to the reported computed value, including any required formatting constraints."
    ],
    "exclusion_conditions": [
      "The artifact content is missing, empty, truncated, or differs from the computed value.",
      "The inspection action does not read or list the output artifact.",
      "No previously computed value exists to compare against.",
      "Agreement is only asserted in reasoning but is not visible in the artifact observation."
    ]
  },
  {
    "name": "VALIDATES_IMPLEMENTATION_WITH_EXECUTED_TEST",
    "definition": "The agent authors an executable test or self-check that encodes explicit expected outcomes for a component's behavior, executes that authored test against the component, and the reported result is used to determine whether the component's behavior matches the expectations.",
    "parameters": [
      {
        "name": "test_authoring_action",
        "type": "action",
        "description": "The action that creates or writes the executable test or self-check, including assertions or expected values."
      },
      {
        "name": "test_execution_action",
        "type": "action",
        "description": "The action that runs the authored test against the component."
      },
      {
        "name": "test_result_observation",
        "type": "observation",
        "description": "The observation reporting the test's actual outputs, pass/fail status, or assertion results."
      }
    ],
    "assertion_conditions": [
      "The test authoring action produces an executable test or self-check containing at least one explicit expected outcome or assertion about behavior.",
      "The test execution action runs that authored test against the target component.",
      "The observation reports outcomes sufficient to determine whether the test passed or failed."
    ],
    "exclusion_conditions": [
      "The test is only written or inspected but never executed.",
      "The executed command is not the authored test or contains no behavioral assertions or expected outcomes.",
      "The observation is unrelated to the test or provides no pass/fail evidence."
    ]
  },
  {
    "name": "VERIFIES_OUTPUT_AGAINST_STATED_REQUIREMENTS",
    "definition": "A validation action tests produced outputs against requirements or expected properties explicitly stated in reasoning, and its result observation reports evidence about whether those checks passed.",
    "parameters": [
      {
        "name": "validation_action",
        "type": "action",
        "description": "The tool invocation that executes checks, assertions, or comparisons against the produced outputs."
      },
      {
        "name": "criteria_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the requirements or expected properties to validate."
      },
      {
        "name": "validation_observation",
        "type": "observation",
        "description": "The observation reporting the check results or observed values relevant to the stated criteria."
      }
    ],
    "assertion_conditions": [
      "The criteria reasoning states specific requirements, properties, or expected values to be checked.",
      "The validation action executes assertions, inspections, or comparisons targeting those requirements.",
      "The validation observation reports pass/fail status or observed values that address the stated criteria."
    ],
    "exclusion_conditions": [
      "The action generates output rather than checking it against criteria.",
      "The observation merely displays output without comparison to stated requirements.",
      "No explicit validation criteria are stated in the reasoning."
    ]
  },
  {
    "name": "VERIFIES_DEPLOYED_SERVICE_WITH_REQUEST",
    "definition": "After a service or component has been brought up, the reasoning identifies a specific behavior or requirement of the running service to verify, an action exercises the live service through its exposed interface, and the resulting observation reports a response that can be judged against the expected behavior.",
    "parameters": [
      {
        "name": "verification_reasoning",
        "type": "reasoning",
        "description": "Agent text identifying the deployed/running service behavior, endpoint, or requirement that is to be verified."
      },
      {
        "name": "request_action",
        "type": "action",
        "description": "The action that exercises the running service through its exposed interface, such as sending a request to its endpoint."
      },
      {
        "name": "response_observation",
        "type": "observation",
        "description": "The observation containing the service's response content, status, or other output relevant to the verification goal."
      }
    ],
    "assertion_conditions": [
      "The verification_reasoning identifies a specific behavior, endpoint, or requirement of a service that has been deployed or started and now must be confirmed.",
      "The request_action targets that running service through its exposed interface rather than merely reading configuration, files, or process status.",
      "The response_observation reports response content, status, or other output that can be compared with the expected behavior stated or implied by the verification goal."
    ],
    "exclusion_conditions": [
      "The service has not been started or deployed at the time the request is made.",
      "The action only inspects process state, files, logs, or configuration instead of exercising the running service interface.",
      "The request_action is unrelated to the stated verification goal.",
      "The observation reports only a transport failure or no interpretable service response.",
      "No verification goal or expected behavior is stated or implied in the reasoning."
    ]
  },
  {
    "name": "STAGES_CHEAP_PROBE_BEFORE_COSTLY_VALIDATION",
    "definition": "The reasoning orders verification into two tiers, deciding that a fast reduced-scale check is performed first while the expensive full-scale validation is deferred until after that probe, and the corresponding actions execute the reduced check followed by the complete required workload.",
    "parameters": [
      {
        "name": "sequencing_reasoning",
        "type": "reasoning",
        "description": "The agent text expressing the intent to run a quick reduced check before the full or expensive validation."
      },
      {
        "name": "precursor_check_action",
        "type": "action",
        "description": "The action executing the reduced or small-scale check."
      },
      {
        "name": "full_validation_action",
        "type": "action",
        "description": "The action executing the complete, expensive, required workload after the precursor check."
      }
    ],
    "assertion_conditions": [
      "The reasoning expresses the intent to perform a quick or small-scale check before the full or expensive validation.",
      "The precursor action exercises a reduced or small-scale case rather than the complete required workload.",
      "The full validation action exercises the complete required workload and occurs after the precursor action."
    ],
    "exclusion_conditions": [
      "Only one of the two verification steps is performed.",
      "The first action already exercises the full workload rather than a reduced case.",
      "The reasoning does not order the checks by cost or scale.",
      "The precursor check and the full validation are not linked as stages of the same verification effort."
    ]
  }
]

